(()=>{'use strict';const section=document.querySelector('#zemer-cycling'),dialog=document.querySelector('#zmLightbox');if(!section||!dialog)return;const buttons=[...section.querySelectorAll('[data-zm-photo]')],full=document.querySelector('#zmFullImage'),counter=document.querySelector('#zmCounter');let index=0,lastButton=null;const t=s=>window.I18N?.t(s)||s;function show(i){index=(i+buttons.length)%buttons.length;const image=buttons[index].querySelector('img');full.src=image.getAttribute('src');full.alt=image.alt;counter.textContent=(index+1)+' / '+buttons.length}function close(){dialog.close();lastButton?.focus()}section.addEventListener('click',e=>{const button=e.target.closest('[data-zm-photo]');if(!button)return;lastButton=button;show(Number(button.dataset.zmPhoto));if(typeof dialog.showModal==='function')dialog.showModal();else window.open(full.src,'_blank','noopener')});document.querySelector('#zmClose').addEventListener('click',close);document.querySelector('#zmPrevious').addEventListener('click',()=>show(index-1));document.querySelector('#zmNext').addEventListener('click',()=>show(index+1));dialog.addEventListener('click',e=>{if(e.target===dialog)close()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}});dialog.addEventListener('close',()=>lastButton?.focus());function labels(){buttons.forEach((b,i)=>{b.setAttribute('aria-label',t('عرض الصورة')+' '+(i+1));b.querySelector('img').alt=t('مسيرة الدراجات — زيمر')+' · '+(i+1)});dialog.setAttribute('aria-label',t('مسيرة الدراجات — زيمر'));document.querySelector('#zmClose').setAttribute('aria-label',t('إغلاق'));document.querySelector('#zmPrevious').setAttribute('aria-label',t('الصورة السابقة'));document.querySelector('#zmNext').setAttribute('aria-label',t('الصورة التالية'))}labels();window.addEventListener('languagechange',labels);const video=section.querySelector('video');video.addEventListener('play',()=>{document.querySelectorAll('video').forEach(v=>{if(v!==video&&!v.paused)v.pause()})});})();
